import re
def decls(path):
    out=[];ns=[]
    for line in open(path):
        m=re.match(r'^namespace\s+(\S+)', line)
        if m: ns.append(m.group(1)); continue
        if re.match(r'^end\s+\S+', line) and ns:
            if ns[-1]==line.split()[1]: ns.pop()
            continue
        m=re.match(r'^(?:@\[[^\]]*\]\s*)?(?:private\s+|protected\s+|noncomputable\s+|scoped\s+)*(theorem|lemma|def|abbrev|structure|class|instance|inductive)\s+([A-Za-z_][^\s({\[:]*)', line)
        if m: out.append('.'.join(ns+[m.group(2)]))
    return set(out)
for m in ['Albanese/DifferenceMap','Albanese/Milne33Substeps','Albanese/PolePurity','Albanese/RationalMapFunctionField','Albanese/RationalMapProd','Albanese/RationalMapPrecomp']:
    a=decls(f'Algebraic-Jacobian-Challenge/AlgebraicJacobian/{m}.lean')
    b=decls(f'Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/{m}.lean')
    print(f'=== {m}')
    print('  only in Rebuild:', sorted(b-a))
    print('  only in AJC    :', sorted(a-b))
EOF
